/* @lc app=leetcode id=2555 lang=kotlin */ class Solution { fun maximizeWin(prizePositions: IntArray, k: Int): Int = prizePositions.indices.fold(Triple(0, arrayListOf(0), 0)) { (l, pm, ans), r -> generateSequence(l) { it + 1 }.first { prizePositions[r] - prizePositions[it] <= k }.let { nl -> (r - nl + 1).let { w -> maxOf(ans, w + pm[nl]).let { a2 -> Triple(nl, pm.also { it.add(maxOf(it.last(), w)) }, a2) } } } }.third }